reference_solution:
def self_dividing_numbers(left, right):
    answer=[]
    for value in range(left,right+1):
        remaining=value
        while remaining and remaining%10 and value%(remaining%10)==0:remaining//=10
        if remaining==0:answer.append(value)
    return answer

